WITH monthly AS (SELECT SUBSTR(o.ordered_at,1,7) AS month,SUM(i.quantity*i.unit_price_cents) AS revenue_cents FROM orders o JOIN order_items i ON i.order_id=o.order_id WHERE o.status='paid' GROUP BY SUBSTR(o.ordered_at,1,7)) SELECT month,revenue_cents,SUM(revenue_cents) OVER(ORDER BY month ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_cents FROM monthly ORDER BY month;
